import{_ as a,c as i,o as t,ah as s,ao as o,ap as n}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse(`{"title":"Pets in Heaven — Them, Heaven, and Your Grief","description":"For anyone grieving a pet: what the Bible says about animals, eternity, and God's care — four gentle readings to hold you.","frontmatter":{"title":"Pets in Heaven — Them, Heaven, and Your Grief","description":"For anyone grieving a pet: what the Bible says about animals, eternity, and God's care — four gentle readings to hold you."},"headers":[],"relativePath":"en/pets-in-heaven/index.md","filePath":"en/pets-in-heaven/index.md"}`),l={name:"en/pets-in-heaven/index.md"};function r(p,e,h,d,c,m){return t(),i("div",null,[...e[0]||(e[0]=[s('<div class="pl-quote"><p>“After they died, the only thing I really wanted to know was this: are they okay? Will we ever see each other again?”</p><p class="pl-quote-soft">The Bible doesn&#39;t answer every question in one sentence — but it gives enough light to see hope even in the darkest night.</p></div><section class="pl-section"><h2>Before you begin</h2><p class="pl-lead">This is not a place that asks you to &quot;move on&quot; quickly. These four readings are for you — still missing them.</p><p>Losing an animal companion is a particular kind of grief. People say things like &quot;it was just a dog&quot; or &quot;just get another one&quot; — but you know that isn&#39;t true. They knew the sound of your footsteps coming home. In your hardest year, they stayed pressed against your feet. What left with them was the first pair of eyes that greeted you every morning.</p><p>The Bible actually says a great deal about animals. God created them, feeds them, makes a covenant with them, and places them inside the world He promises to renew. These verses don&#39;t prove that &quot;every pet is in heaven&quot; — the Bible doesn&#39;t promise that — but they reveal something tender: <strong>in God&#39;s plan, animals were never disposable extras.</strong></p><p>May what you find here be more than verses — may it be the God who remembers even a sparrow, remembering yours.</p></section><section class="pl-section"><h2>Four readings for you</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/en/pets-in-heaven/will-i-see-my-pet-again">Will I See My Pet Again?</a></h3><p>The hope of the Bible for animals and heaven — creation itself waits for redemption, and the new creation still has animals in it.</p><p class="pl-quote-soft">Romans 8:19-22 · Isaiah 11:6-9 · Revelation 21:4-5</p></div><div class="pl-new-card"><h3><a href="/en/pets-in-heaven/not-one-sparrow-forgotten">Not One Sparrow Is Forgotten</a></h3><p>They were so small — will the world remember them? Jesus said not one sparrow falls without your Father knowing.</p><p class="pl-quote-soft">Matthew 10:29-31 · Psalm 147:9 · Psalm 36:6</p></div><div class="pl-new-card"><h3><a href="/en/pets-in-heaven/rainbow-bridge-covenant">Beyond the Rainbow Bridge</a></h3><p>“Rainbow Bridge” is a beautiful image — and the Bible really does have a rainbow: God&#39;s everlasting covenant with <em>every living creature</em>.</p><p class="pl-quote-soft">Genesis 9:9-13 · Isaiah 65:25 · Revelation 5:13</p></div><div class="pl-new-card"><h3><a href="/en/pets-in-heaven/permission-to-grieve">Permission to Grieve</a></h3><p>God keeps your tears in a bottle. Grief is not a lack of faith — it is love still going on.</p><p class="pl-quote-soft">Psalm 56:8 · Psalm 34:18 · Matthew 5:4</p></div></div></section><section class="pl-section"><h2>How to read these</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>Slowly — not all at once</h3><p>One paragraph is enough. If a verse makes you cry, stop there. That isn&#39;t weakness; that is love moving.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>Put their name into the verse</h3><p>When you read “He gives to the beast its food,” try their name in that sentence. God cared for them like that, too.</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>Say one thing to them afterwards</h3><p>It doesn&#39;t need to be beautiful. “I miss you” is enough. If you want to say more, the guided journal in PetLoss will sit with you.</p></div></div></section><section class="pl-section"><h2>Every Verse in One Place</h2><p class="pl-lead">Every passage referenced across these four readings, gathered in one place to read again and look up slowly.</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/en/pets-in-heaven/will-i-see-my-pet-again">Will I See My Pet Again?</a></h3><ul class="pl-verse-list"><li>Romans 8:19-22</li><li>Isaiah 11:6-9</li><li>Revelation 21:4-5</li><li>Psalm 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/en/pets-in-heaven/not-one-sparrow-forgotten">Not One Sparrow Is Forgotten</a></h3><ul class="pl-verse-list"><li>Matthew 10:29-31</li><li>Psalm 147:9</li><li>Psalm 36:6</li><li>Psalm 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/en/pets-in-heaven/rainbow-bridge-covenant">Beyond the Rainbow Bridge</a></h3><ul class="pl-verse-list"><li>Genesis 9:9-13</li><li>Isaiah 65:25</li><li>Revelation 5:13</li><li>Psalm 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/en/pets-in-heaven/permission-to-grieve">Permission to Grieve</a></h3><ul class="pl-verse-list"><li>Psalm 56:8</li><li>Psalm 34:18</li><li>Psalm 147:3</li><li>Matthew 5:4</li><li>John 11:35</li><li>Revelation 21:4</li></ul></div></div></section><div class="pl-cta"><h2>May you be gently held here.</h2><p>If you want somewhere to keep their photos and write the words you never got to say, PetLoss will quietly stay with you — no account, no uploads, fully offline.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Download on the App Store</a><p class="pl-disclaimer">These readings offer faith reflection and emotional companionship; they are not medical, psychological, or therapeutic advice. If grief keeps you from functioning for a long period, please reach out to a licensed professional or a local support line. Scripture quotations are from the King James Version (KJV).</p></div><div class="pl-bible"><h3>Let the words of Scripture stay with you</h3><p>Every verse across these four readings comes from the Bible. With Rainbow Bible you can read Scripture anytime and set a daily verse widget — a small light for the days you miss them.</p><div class="pl-bible-shots"><figure><img src="'+o+'" alt="Rainbow Bible home-screen widget showing 2 Timothy 2:13" loading="lazy"><figcaption>Daily verse on your Home Screen</figcaption></figure><figure><img src="'+n+'" alt="Rainbow Bible app — Pets in Heaven topic showing Matthew 10:29-31" loading="lazy"><figcaption>Read Scripture in the Pets in Heaven topic</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Get Rainbow Bible on the App Store</a></div>',7)])])}const g=a(l,[["render",r]]);export{v as __pageData,g as default};
